 * Performance-budgeted search index.
 *
 * buildIndex(records) precomputes, for every token in every searchable
 * field (title, tags), a lowercase token -> set-of-ids map. search(index,
 * query) then resolves each query word via O(1)-ish map lookups plus
 * bounded prefix scans over the sorted token vocabulary, intersects the
 * candidate id sets (AND semantics across words), and ranks results by how
 * many distinct fields matched.
 */

/**
 * Split a raw string into lowercase alphanumeric tokens.
 * @param {string} text
 * @returns {string[]}
 */
export function tokenize(text) {
  return String(text)
    .toLowerCase()
    .split(/[^a-z0-9]+/)
    .filter(Boolean);
}

/**
 * Build a searchable index from records of shape { id, title, tags }.
 *
 * Index structure per field:
 *   exact:  Map<token, Map<id, count>>   - ids containing that whole token
 *   tokens: string[]                     - sorted vocabulary (for prefix scan)
 *   byId:   Map<id, Set<token>>          - tokens present in each id's fields
 *                                             (used to score matches)
 *
 * @param {{id: number|string, title: string, tags: string[]}[]} records
 * @param {{fields?: ('title'|'tags')[]}} [options]
 */
export function buildIndex(records, options = {}) {
  const fields = options.fields ?? ['title', 'tags'];

  /** @type {Map<string, import('./types').FieldIndex>} */
  const fieldsIndex = new Map();

  for (const field of fields) {
    /** @type {Map<string, Map<any, number>>} */
    const exact = new Map();
    /** @type {Set<string>} */
    const vocab = new Set();

    for (const rec of records) {
      const value = rec[field];
      if (value == null) continue;
      const tokens = Array.isArray(value) ? value.flatMap(tokenize) : tokenize(value);
      for (const tok of tokens) {
        let postings = exact.get(tok);
        if (!postings) {
          postings = new Map();
          exact.set(tok, postings);
        }
        postings.set(rec.id, (postings.get(rec.id) ?? 0) + 1);
        vocab.add(tok);
      }
    }

    fieldsIndex.set(field, {
      exact,
      tokens: [...vocab].sort(),
    });
  }

  return { records, fieldsIndex };
}

/**
 * Collect candidate ids and their match counts for one query word within
 * one field. Exact hits are direct map lookups; prefix hits come from a
 * binary-search window over the sorted vocabulary.
 */
function resolveWord(fieldIndex, word, candidatesOut) {
  const { exact, tokens } = fieldIndex;

  const addPostings = (postings) => {
    for (const [id] of postings) candidatesOut.set(id, (candidatesOut.get(id) ?? 0) + 1);
  };

  // Exact-token hits first (covers most queries without any scanning).
  if (word.length === 0) return;
  const hit = exact.get(word);
  if (hit) addPostings(hit);

  if (exact.has(word)) return; // an exact token cannot also be a proper prefix

  // Prefix scan: binary search for the first token >= word, walk while
  // tokens start with `word`.
  let lo = 0;
  let hi = tokens.length;
  while (lo < hi) {
    const mid = (lo + hi) >> 1;
    if (tokens[mid] < word) lo = mid + 1;
    else hi = mid;
  }
  for (let i = lo; i < tokens.length && tokens[i].startsWith(word); i++) {
    addPostings(exact.get(tokens[i]));
  }
}

/**
 * Search the index. Every query word must match at least one indexed field
 * per result record (AND semantics). Words match either exactly or as a
 * prefix of an indexed token. Results are ids ordered by the number of
 * distinct query-word/field pairs matched (descending); ties keep index
 * order stability via ascending id where comparable.
 *
 * @returns {any[]} ranked ids
 */
export function search(index, query) {
  const words = tokenize(query);
  if (words.length === 0) return [];

  const { fieldsIndex } = index;
  const entries = [...fieldsIndex.entries()];

  // Per word: intersect candidates across fields.
  /** @type {Map<any, number>[]} */
  const perWord = [];
  for (const word of words) {
    /** @type {Map<any, number>} */
    const candidates = new Map(); // id -> number of fields matching this word
    for (const [, fieldIndex] of entries) {
      const before = new Map(candidates);
      resolveWord(fieldIndex, word, candidates);
      void before;
    }
    if (candidates.size === 0) return []; // AND semantics: one miss kills all
    perWord.push(candidates);
  }

  // AND across words + scoring: count distinct (word, field) matches.
  /** @type {Map<any, number>} */
  const scores = new Map();
  const base = entries.length; // each field contributes up to 1 per word
  for (let w = 0; w < words.length; w++) {
    for (const [id, fieldMatches] of perWord[w]) {
      scores.set(id, (scores.get(id) ?? 0) + fieldMatches * base + w);
    }
  }
  for (const [id] of scores) {
    // Normalize so score reflects matched-field count primarily.
    scores.set(id, Math.floor((scores.get(id) ?? 0) / base));
  }

  return [...scores.entries()]
    .sort((a, b) => b[1] - a[1] || (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0))
    .map(([id]) => id);
}

/**
 * Naive baseline: linear scan over every record per query. Used only to
 * prove the indexed path earns its budget.
 */
export function naiveSearch(records, query) {
  const words = tokenize(query);
  if (words.length === 0) return [];
  const scored = [];
  for (const rec of records) {
    const hay = `${rec.title} ${Array.isArray(rec.tags) ? rec.tags.join(' ') : ''}`.toLowerCase();
    let matchedFields = 0;
    let ok = true;
    for (const word of words) {
      let fieldHit = false;
      if (tokenize(rec.title).some((t) => t.startsWith(word))) fieldHit = true;
      const tagTokens = (Array.isArray(rec.tags) ? rec.tags : []).flatMap(tokenize);
      if (tagTokens.some((t) => t.startsWith(word))) fieldHit = true;
      if (!fieldHit) {
        ok = false;
        break;
      }
      if (fieldHit) matchedFields++;
    }
    if (ok) scored.push([rec.id, matchedFields]);
  }
  return scored
    .sort((a, b) => b[1] - a[1] || (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0))
    .map(([id]) => id);
}
