 * @param {{fields?: string[]}} [options]
 * @returns {{records: unknown[], fieldsIndex: Map<string, FieldIndex>}}
 */
export function buildIndex(records, options = {}) {
  const fields = options.fields ?? ['title', 'tags'];
  /** @type {Map<string, FieldIndex>} */
  const fieldsIndex = new Map();

  for (const field of fields) {
    /** @type {Map<string, Set<any>>} */
    const exact = new Map();
    /** @type {Set<string>} */
    const vocab = new Set();

    for (const rec of records) {
      const value = rec[field];
      if (value == null) continue;
      const tokens = Array.isArray(value) ? value.flatMap(tokenize) : tokenize(value);
      for (const tok of tokens) {
        let postings = exact.get(tok);
        if (!postings) {
          postings = new Set();
          exact.set(tok, postings);
        }
        postings.add(rec.id);
        vocab.add(tok);
      }
    }

    fieldsIndex.set(field, { exact, tokens: [...vocab].sort() });
  }

  return { records, fieldsIndex };
