/**
 * All ids whose field contains a token equal to `word` or prefixed by it.
 * One binary search locates the start of the prefix window; the walk then
 * touches only matching postings. Cost is independent of record count.
 */
function* resolveWordIds(fieldIndex, word) {
  const { exact, tokens } = fieldIndex;
  let lo = 0;
  let hi = tokens.length;
  while (lo < hi) {
    const mid = (lo + hi) >> 1;
    if (tokens[mid] < word) lo = mid + 1;
    else hi = mid;
  }
  for (let i = lo; i < tokens.length && tokens[i].startsWith(word); i++) {
    yield* exact.get(tokens[i]);
  }
