 * @param {{fieldsIndex: Map<string, FieldIndex>}} index
 * @param {string} query
 * @returns {any[]} matching ids, best first (see module docs for ranking)
 */
export function search(index, query) {
  const words = tokenize(query);
  const nFields = index.fieldsIndex.size;
  if (words.length === 0 || nFields === 0) return [];

  const entries = [...index.fieldsIndex.entries()];
  /** id -> bitmask of fields that matched some word so far (AND across words) */
  let acc = null;

  for (const word of words) {
    /** id -> bitmask of fields matching THIS word */
    const cur = new Map();
    for (let fi = 0; fi < nFields; fi++) {
      const bit = 1 << fi;
      for (const id of resolveWordIds(entries[fi][1], word)) {
        cur.set(id, (cur.get(id) ?? 0) | bit);
      }
    }
    if (cur.size === 0) return []; // AND semantics: a miss kills everything

    if (acc === null) {
      acc = cur;
    } else {
      for (const [id, mask] of acc) {
        const other = cur.get(id);
        if (other === undefined) acc.delete(id);
        else acc.set(id, mask | other);
      }
      if (acc.size === 0) return [];
    }
  }

  return [...acc]
    .map(([id, mask]) => [id, popcount(mask)])
    .sort((a, b) => b[1] - a[1] || (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0))
    .map(([id]) => id);
}

