 * field, where every token is preceded by a space. A word prefix-matches a
 * field iff the field string contains `' ' + word`.
 *
 * Preparation cost mirrors buildIndex and is paid ONCE (outside timing),
 * keeping the comparison honest: what remains per naive query is a genuine
 * linear scan over every record.
 *
 * @returns {string[][]} docs[i][f] = padded field string for record i, field f
 */
export function prepareNaiveDocs(records, options = {}) {
  const fields = options.fields ?? ['title', 'tags'];
  return records.map((rec) =>
    fields.map((f) => {
      const value = rec[f];
      if (value == null) return ' ';
      const text = Array.isArray(value) ? value.join(' ') : String(value);
      return ` ${text.toLowerCase().replace(/[^a-z0-9]+/g, ' ')} `;
