];

const pick = (rng, arr) => arr[(rng() * arr.length) | 0];

/**
 * Generate `count` deterministic records { id, title, tags }.
 *
 * @param {number} [count]
 * @param {number} [seed]
 * @returns {{id: number, title: string, tags: string[]}[]}
 */
export function generateRecords(count = 50000, seed = 20260824) {
  const rng = mulberry32(seed);
  const records = new Array(count);
  for (let i = 0; i < count; i++) {
    const nTags = 2 + ((rng() * 2) | 0); // 2 or 3 tags
    const tags = new Set();
    while (tags.size < nTags) tags.add(pick(rng, TAG_POOL));
    const suffix = rng() < 0.35 ? ` ${pick(rng, NOUNS)} ${((rng() * 900) + 100) | 0}` : '';
    records[i] = {
      id: i,
      title: `${pick(rng, ADJECTIVES)} ${pick(rng, NOUNS)} ${pick(rng, KINDS)}${suffix}`,
      tags: [...tags],
    };
  }
  return records;
}

/**
 * Pick `count` varied but deterministic queries derived from the corpus:
 * whole words, short prefixes, co-occurring multi-word ANDs (taken straight
 * from real titles), cross-field ANDs (title word + tag), and guaranteed
 * misses. Exercises hot paths AND cold paths of the resolver.
 *
 * @param {ReturnType<typeof generateRecords>} records
 * @param {number} [count]
 * @param {number} [seed]
 * @returns {string[]}
 */
export function pickQueries(records, count = 200, seed = 1337) {
  const rng = mulberry32(seed);
  const titleWords = new Set();
  const tags = new Set(TAG_POOL);
  for (const rec of records) {
    for (const tok of rec.title.toLowerCase().split(/\s+/)) titleWords.add(tok);
  }
  const words = [...titleWords].filter((w) => /^[a-z]{3,}$/.test(w));

  const queries = [];
  while (queries.length < count) {
    const kind = (rng() * 5) | 0;
    if (kind === 0) {
      queries.push(pick(rng, words)); // single whole word
    } else if (kind === 1) {
      queries.push(pick(rng, words).slice(0, 2 + ((rng() * 3) | 0))); // short prefix
    } else if (kind === 2) {
      // two words from ONE real title => non-trivial AND hit
      const t = records[(rng() * records.length) | 0].title.toLowerCase().split(/\s+/);
      queries.push(`${t[0]} ${t[2] ?? t[1]}`);
    } else if (kind === 3) {
      // title word AND tag => cross-field AND
      queries.push(`${pick(rng, words)} ${pick(rng, [...tags])}`);
    } else {
      // guaranteed miss (no such token anywhere)
      queries.push(`zzqq${((rng() * 999) | 0)}x`);
    }
  }
  return queries.slice(0, count);
}

